from pathlib import Path
import json,hashlib
W=Path(__file__).resolve().parent;ROOT=W.parents[1];H=W/'shibuki_audit'
def rec(p):return {'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
files=[H/f'nova_ultimate_pack01/{form}_readback_{i:02}.png'for form in('before','after')for i in(0,1)]+[H/f'nova_ultimate_pack01/partial_{i}.png'for i in(213,215)]+[H/f'nova_ultimate_sequence01/{form}_preparation_order.png'for form in('before','after')]
p=W/'root_review_checkpoint149.json';assert not p.exists();p.write_text(json.dumps({'checkpoint':149,'candidate_sha256':'687fb27b10b9a7c13dd6d0c9fd6976dbb04f88f9b3b775f3d33482ebb7efb86f','actually_viewed_files':[dict(rec(f),actually_viewed=True)for f in files],'observations':['Ultimate 준비213..216의 획득 전후 재추출4판·부분2판·원순서2판을 직접 열람했다.','대기 기준 귀·머리·금색 머리장식·의상 세부 및 굽힌/뻗은 다리의 작은 신발을 확인했다. 추가 확정 몸 분리는 찾지 못했다.','217 이후 강제15의 기존 재킷 돌진몸은 이번 새 준비4와 다른 미완료 범위로 남긴다.'],'limits':['실제 노바/60Hz 전수 검증은 아니다.','부분마스크 표는 자료구조 조합표이며 전부 도달 가능한 실제 Ultimate 상태를 뜻하지 않는다.'],'stage':'정적 미술검토; 독립검사/동결 후 시험본 통합 가능','whole_project_complete':False},ensure_ascii=False,indent=2)+'\n','utf8');print('149',rec(p)['sha256'])
p=W/'root_review_checkpoint150.json';assert not p.exists();p.write_text(json.dumps({'checkpoint':150,'candidate_sha256':'619032d0b81ffc50e5f5664ff1e3d0c077f226a7d5a8ccfac081be6a2126c6c5','prior_review':rec(W/'root_review_checkpoint147.json'),'actually_viewed_files':[dict(rec(H/f'nova_base_sequence02/{form}_preparation_order.png'),actually_viewed=True)for form in('base','fourth')],'correction':rec(H/'prepared_nova_base01/sequence_mask_correction.json'),'observations':['기본형은 원renderer 마스크0,포스는15로 표시한 수정 원순서2판을 직접 열람했다.','옛sequence01의 기본217/220 각528픽셀은 강제15를 잘못 적용한 미리보기 오류였다. 새213..216 그림과 후보ARC619032는 변경되지 않았다.','root147의 최종재추출/부분조합6판은 유지하고 원순서 근거는 이2판으로 대체한다.'],'limits':['원본 게임코드 변경이나 실제 인게임 버그수정은 아니다.','217..220은 기존그림이며 준비4의 완료범위에 포함하지 않는다.'],'whole_project_complete':False},ensure_ascii=False,indent=2)+'\n','utf8');print('150',rec(p)['sha256'])
